{"newText":"/// Docs cross-link rewrite: relative `*.md` links point at the surfaced
/// /docs/ page when curated, else at the GitHub source.
String Function(String) docsLinkRewriter() {
  final byFile = {
    for (final d in docsRegistry) d.source.split('/').last: d.slug,
  };
  return (href) {
    if (RegExp(r'^(?:https?:)?//|^#|^mailto:').hasMatch(href)) return href;
    if (href.endsWith('.md')) {
      final file = href.split('/').last;
      final slug = byFile[file];
      if (slug != null) return '/docs/$slug/';
      return '$repoUrl/blob/main/docs/${_normalizeRepoRelative(href)}';
    }
    return href;
  };
}

/// Resolves `.`/`..` segments out of a repo-relative href so parent-
/// relative links like `../foo.md` never leak `..` into a published URL.
/// `..` is clamped at the repo root.
String _normalizeRepoRelative(String href) {
