    test('llms.txt and llms-full.txt serve 200 text/plain', () async {
      for (final path in ['/llms.txt', '/llms-full.txt']) {
        final (status, body, type) = await get(path);
        expect(status, 200, reason: path);
        expect(type, 'text/plain', reason: path);
