      expect(index, contains('./outlook/manifest.xml'));
      expectMentioned(index, outlookTools, 'site/index.html');
      expect(
        index,
        contains('id="addons"'),
        reason: 'the add-ons section anchors the nav + hero links',
      );
      expect(index, contains('href="#addons"'));
    },
  );

