      () async {
        final (status, body, type) = await get('/robots.txt');
        expect(status, 200);
        expect(type, 'text/plain');
        for (final bot in [
          'GPTBot',
          'OAI-SearchBot',
          'ChatGPT-User',
          'Google-Extended',
          'ClaudeBot',
          'anthropic-ai',
          'PerplexityBot',
          'Perplexity-User',
          'CCBot',
          'Applebot-Extended',
          'Meta-ExternalAgent',
        ]) {
          expect(
            body,
