            reason: '$bot must be welcomed by name',
          );
        }
        expect(body, contains('User-agent: *\nAllow: /'));
        expect(body, contains('https://fa1.dev/llms.txt'));
        expect(body, contains('https://fa1.dev/llms-full.txt'));
