    origin = 'http://127.0.0.1:${server.port}';
    server.listen((req) async {
      final path = Uri.decodeComponent(req.uri.path);
      final file = resolveSiteFile(siteRoot.path, path);
      if (file == null) {
        req.response
          ..statusCode = HttpStatus.notFound
