/// `site/app/` (the separately-assembled Flutter web demo, gitignored).
void _copyStaticSite(String root, String outDir) {
  final src = Directory('$root/site');
  final skipDirs = _generatedPageDirs(root).toSet();
  bool skip(String rel) =>
      rel == 'app' ||
      rel.startsWith('app/') ||
      skipDirs.any((d) => rel == d.substring(5) || rel.startsWith('${d.substring(5)}/'));
  for (final entity in src.listSync(recursive: true)) {
    final rel = entity.path.substring(src.path.length + 1).replaceAll('\\', '/');
    if (entity is Directory) {
      if (!skip(rel)) Directory('$outDir/$rel').createSync(recursive: true);
    } else if (entity is File) {
      if (skip(rel)) continue;
      // Generated top-level artifacts are written from [outputs].
      if (rel == 'sitemap.xml' || rel == 'llms-full.txt') continue;
      final dest = File('$outDir/$rel')..createSync(recursive: true);
      dest.writeAsBytesSync(entity.readAsBytesSync());
    }
  }
}

/// Writes [outputs] (site-relative paths) into the target tree — the repo
/// itself when [outDir] is null (local preview into the gitignored paths),
/// otherwise a complete copy under [outDir] (CI validation / pages.yml
/// deploy). Stale generated page dirs in the target are pruned.
void emitSite({
  required String root,
  String? outDir,
  required List<OutputFile> outputs,
}) {
  final target = outDir ?? root;
  if (outDir != null) _copyStaticSite(root, outDir);
  for (final o in outputs) {
    final f = File('$target/${o.path}')..createSync(recursive: true);
    f.writeAsStringSync(o.content);
  }
  // Prune generated pages whose source disappeared.
  final expectedPaths = {for (final o in outputs) o.path};
  for (final dir in _generatedPageDirs(target)) {
    if (!expectedPaths.any((p) => p.startsWith('$dir/'))) {
      Directory('$target/$dir').deleteSync(recursive: true);
      stdout.writeln('pruned stale page: $dir/');
    }
  }
  stdout.writeln(
    'site built: ${outputs.length} artifact(s) — blog posts, docs pages, '
    'sitemap.xml, llms-full.txt${outDir != null ? ' -> $outDir' : ''}',
  );
}

