String? parseArgs(List<String> args) {
  String? outDir;
  for (var i = 0; i < args.length; i++) {
    final a = args[i];
    if (a == '--out') {
      if (i + 1 >= args.length) {
        throw const FormatException('--out requires a target directory');
      }
      outDir = args[++i];
    } else if (a == '--check') {
