/// unrecognized — a typo must never silently fall back to an in-tree
/// build (gh-1476 review).
String? parseArgs(List<String> args) {
  String? outDir;
  for (var i = 0; i < args.length; i++) {
    final a = args[i];
    if (a == '--out') {
      if (i + 1 >= args.length) {
        throw const FormatException('--out requires a target directory');
      }
      outDir = args[++i];
    } else if (a == '--check') {
      throw const FormatException(
        '`--check` was removed (gh-1476 owner directive, PR #1479): '
        ...
      );
    } else {
      throw FormatException('unknown argument: $a');
    }
  }
  return outDir;
}

void main(List<String> args) {
  final String? outDir;
  try {
    outDir = parseArgs(args);
  } on FormatException catch (e) {
    stderr.writeln(e.message);
    stderr.writeln('usage: dart scripts/build_site.dart [--out <dir>]');
    exit(2);
  }
  final root = _repoRoot();
  emitSite(root: root, outDir: outDir, outputs: buildSite(root: root));
}
